import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

interface Monitoring {
  total: number;
  used: number;
}

@Controller('api/v1')
export class FnSfr03803Controller {
  @Get('/server-capacities')
  async getServerCapacity(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const info = this.readMonitoring();
    if (info === null || !Number.isFinite(info.total) || !Number.isFinite(info.used)) {
      throw new ApiError(502, 'SERVER_CAPACITY_UNAVAILABLE', '서버 모니터링 정보를 가져오지 못했습니다.');
    }
    return {
      totalCapacity: info.total,
      usedCapacity: info.used,
      remainingCapacity: info.total - info.used,
    };
  }

  // 가정: 서버 모니터링 정보의 출처가 스펙에 없어 아직 연결하지 못했다.
  // 연결되면 전체 용량과 사용 용량을 돌려준다. 연결 전에는 null을 돌려 502로 응답한다.
  private readMonitoring(): Monitoring | null {
    return null;
  }
}

