import { ErrorText, Tiles, Num, call, useData } from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr03803Page({ role, notify }: PageProps) {
  const { data, error, loading, reload } = useData<Row>(
    () => call<Row>('GET', '/server-capacities', role),
    [role],
  );

  return (
    <div className="doc">
      <section className="box">
        <h2>서버 사용 용량 현황</h2>
        <button
          className="ghost"
          onClick={() => {
            reload();
            notify('용량 현황을 다시 조회했습니다.');
          }}
        >
          다시 조회
        </button>
        {loading && <p>용량 현황을 불러오는 중입니다.</p>}
        {error !== '' && <ErrorText text={error} />}
        {data !== undefined && (
          <Tiles
            items={[
              ['전체 용량', <Num value={data.totalCapacity} />],
              ['사용 용량', <Num value={data.usedCapacity} />],
              ['잔여 용량', <Num value={data.remainingCapacity} />],
            ]}
          />
        )}
        {!loading && error === '' && data === undefined && (
          <p>표시할 용량 정보가 없습니다. 다시 조회해 주세요.</p>
        )}
      </section>
    </div>
  );
}
